CREATE OR REPLACE FUNCTION public.delivery_reason_photo_register() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.trip_stops; o public.orders; BEGIN IF NEW.reason_photo_url IS NOT NULL THEN SELECT * INTO s FROM public.trip_stops WHERE id=NEW.stop_id;SELECT * INTO o FROM public.orders WHERE id=s.order_id;PERFORM public._photo_register(o.company_id,NEW.reason_photo_url,'delivery','delivery_lines',NEW.order_line_id,s.trip_id,o.customer_id,o.id,NULL,auth.uid(),now());END IF;RETURN NEW; END $$;